  @Description_627a8792cd5e = N'Does this person currently have this entitlement? Asked by Code (the capability), not SKU. PersonID is authoritative; email is a convenience, resolved to one Person by the same rule the checkout uses when several share it (Orders history, then oldest). Access is evaluated (status + window + subscription access-through), never read off EntitlementGrant.Status. Unknown person and known person without access return the same shape. Fail closed. v1 evaluates person grants only.'
SET
  @InputTypeName_627a8792cd5e = N'CheckEntitlementInput'
SET
  @InputTypeDefinition_627a8792cd5e = N'/**
 * Input for `Orders.CheckEntitlement`.
 *
 * Asked by capability Code, not SKU. PersonID is authoritative; email is a convenience
 * resolution (normalised; several Persons sharing it resolve by the checkout''s rule). AsOf is diagnostics only (historical
 * audit). The trust path omits it. Future values are rejected. CacheUntil is always
 * issued from wall-clock now, never from AsOf.
 *
 * NO import statements — definitions are emitted verbatim.
 */
export interface CheckEntitlementInput {
    /** Authoritative person key. When present, Email is ignored. */
    PersonID?: string;
    /** Convenience. Normalised; several matching Persons resolve to one by `ResolvePersonByEmail` (Orders history, then oldest). */
    Email?: string;
    /** `ProductEntitlement.Code` — unique per product, not globally. Convention: APP_AREA_TIER. */
    Code: string;
    /** Diagnostics only (historical audit). Omit on the trust path. Future values are rejected. */
    AsOf?: string;
    /** Optional narrowing via the template product''s company. */
    CompanyID?: string;
}
'
SET
  @InputTypeIsArray_627a8792cd5e = 0
SET
  @OutputTypeName_627a8792cd5e = N'CheckEntitlementOutput'
SET
  @OutputTypeDefinition_627a8792cd5e = N'/**
 * Output for `Orders.CheckEntitlement`.
 *
 * `Decision` is why, not just whether — expired, revoked, never bought, and not-yet-valid
 * are three screens. Unknown person and known-person-without-access share this shape
 * (`HasAccess: false`, `Decision: ''NoGrant''`). Dates are ISO strings.
 *
 * NO import statements — definitions are emitted verbatim.
 */
export type EntitlementDecision =
    | ''Granted''
    | ''NoGrant''
    | ''NotYetValid''
    | ''Expired''
    | ''Revoked''
    | ''Suspended''
    | ''SubscriptionInactive'';

export interface CheckEntitlementOutput {
    HasAccess: boolean;
    Decision: EntitlementDecision;
    ValidFrom?: string;
    /** When access actually ends — grant window, or subscription access-through after cancel. */
    ValidTo?: string;
    /** ResourceQuantity — seats. Null for Feature/AccessLevel. */
    Quantity?: number;
    /** Audit handle of the winning grant. */
    GrantID?: string;
    EvaluatedAt: string;
    /** min(ValidTo, wall-clock now + 60s). Never derived from AsOf. Fail closed when stale. */
    CacheUntil: string;
}
'
